public class OrderSystem {
    public static class Task implements Comparable<Task> {
        private final String title;
        private final int priority;

        public Task(String title, int priority) {
            this.title = title;
            this.priority = priority;
        }

        public int getPriority() { return priority; }
        public String getTitle() { return title; }

        // Modifies the original class to establish natural ordering by priority
        @Override
        public int compareTo(Task other) {
            return Integer.compare(this.priority, other.priority);
        }
    }

    public static void main(String[] args) {
        List<Task> tasks = new ArrayList<>();
        tasks.add(new Task("Refactor", 3));
        tasks.add(new Task("Hotfix", 1));

        // Uses Comparable (natural ordering)
        Collections.sort(tasks);

        // Uses Comparator (external strategy, sorting by title alphabetically)
        tasks.sort(Comparator.comparing(Task::getTitle));
    }
}
